// The example scenes of `scenes/` (generated by `cfd-cli example --all scenes`), bundled by Vite.
import type { Scene } from '../generated/scene.ts'

const modules = import.meta.glob<Scene>('../../../../scenes/*.json', {
  eager: true,
  import: 'default',
})

export interface Example {
  /** File name without `.json`, e.g. `cylinder-re100`. */
  id: string
  scene: Scene
}

export const EXAMPLES: Example[] = Object.entries(modules)
  .map(([path, scene]) => ({ id: path.replace(/^.*\/(.+)\.json$/, '$1'), scene }))
  .sort((a, b) => a.id.localeCompare(b.id))
